456:     //print("gen {}\n", m.name);
457:     if(m.body.is_none()) return;
458:     if(m.is_generic) return;
459:     if(std::getenv("genCode").is_some()){
460:       let s = printMethod(m);
461:       print("emit {:?}\n", s);
462:       s.drop();
463:     }
464:     self.ctx.prog.compile_begin(m);
465:     self.curMethod = Option<Method*>::new(m);
466:     self.own.drop();
467:     self.own = Option::new(Own::new(self, m));
468:     let proto = self.protos.get().get_func(m);
469:     self.protos.get().cur = Option::new(proto.val);
470:     self.NamedValues.clear();
471:     let ll = self.ll.get();
472:     let bb = create_bb(ll.ctx, "entry".ptr(), proto.val);
473:     SetInsertPoint(ll.builder, bb);
474:     self.di.get().dbg_func(m, proto.val, self);
475:     AllocHelper::makeLocals(self, m.body.get());
476:     self.allocParams(m);
477:     self.enter_frame();
478:     self.storeParams(m, proto.val);
479: 
480:     let blk_val = self.visit_block(m.body.get());
481:     let exit = Exit::get_exit_type(m.body.get());
482:     if(!exit.is_exit()){
483:       if(m.type.is_void()){
484:         self.own.get().do_return(m.body.get().end_line);
485:         self.exit_frame();
486:         if(is_main(m)){
487:           CreateRet(ll.builder, ll.makeInt(0, 32));
488:         }else{
489:           CreateRetVoid(ll.builder);
490:         }
491:       }else if(blk_val.is_some() && !m.type.is_void()){
492:         //setField(blk_val.unwrap(), &m.type, );
493:         self.visit_ret(blk_val.unwrap());
494:         self.own.get().do_move(m.body.get().return_expr.get());
495:       }
496:     }
497:     self.di.get().finalize();
498:     verifyFunction(proto.val);
499:     self.own.drop();
500:     self.own = Option<Own>::new();
501:     self.ctx.prog.compile_end(m);
502:     exit.drop();
503:   }
