22: func get_linker(): str{
23:   let opt = std::getenv("LD");
24:   if(opt.is_some()){
25:     return opt.unwrap();
26:   }
27:   let arr = ["clang++-19", "clang++", "g++", "gcc"];
28:   for ld in &arr[0..arr.len()]{
29:     let res = Process::run(*ld).read_close();
30:     if(res.is_ok()){
31:       res.drop();
32:       return *ld;
33:     }
34:   }
35:   panic("can't find linker");
36: }
