148: struct Compiler;
149: impl Compiler{
150:   func compile_single(config: CompilerConfig): Result<String, CompilerError>{
151:     config.use_cache = false;
152:     File::create_dir(config.out_dir.str())?;
153:     let ctx = Context::new(config.out_dir.clone(), config.std_path.clone());
154:     for inc_dir in &config.src_dirs{
155:       ctx.add_path(inc_dir.str());
156:     }
157:     let cache = new_cache(&config);
158:     let cmp = Emitter::new(ctx, &config, &cache);
159:     let compiled = List<String>::new();
160:     if(cmp.ctx.verbose){
161:       print("compiling {}\n", config.trim_by_root(config.file.str()));
162:     }
163:     let obj = cmp.compile(config.file.str());
164:     compiled.add(obj);
165:     let res = config.link(&compiled);
166:     config.drop();
167:     cmp.drop();
168:     compiled.drop();
169:     cache.drop();
170:     return res;
171:   }
172: 
173:   func compile_dir(config: CompilerConfig): Result<String, CompilerError>{
174:     if(config.jobs > 0){
175:       return Compiler::compile_dir_thread(config);
176:     }
177:     File::create_dir(config.out_dir.str())?;
178:     let cache = new_cache(&config);
179:     cache.read_cache();
180:     
181:     let inc = Incremental::new(config.incremental_enabled, config.out_dir.str(), config.file.clone());
182:     let src_dir = &config.file;
183:     let list: List<String> = File::read_dir(src_dir.str()).unwrap();
184:     let compiled = List<String>::new();
185:     for(let i = 0;i < list.len();++i){
186:       let name = list.get(i).str();
187:       if(!name.ends_with(".x")) continue;
188:       let file: String = format("{}/{}", src_dir, name);
189:       if(File::is_dir(file.str())) {
190:         file.drop();
191:         continue;
192:       }
193:       let ctx = Context::new(config.out_dir.clone(), config.std_path.clone());
194:       ctx.verbose_all = config.verbose_all;
195:       for(let j = 0;j < config.src_dirs.len();++j){
196:         ctx.add_path(config.src_dirs.get(j).str());
197:       }
198:       let cmp = Emitter::new(ctx, &config, &cache);
199:       if(cmp.ctx.verbose){
200:         print("compiling [{}/{}] {}\n", i + 1, list.len(), config.trim_by_root(file.str()));
201:       }
202:       let obj = cmp.compile(file.str());
203:       compiled.add(obj);
204:       cmp.drop();
205:       file.drop();
206:     }
207:     for rec_file in &cache.inc.recompiles{
208:       let file: String = format("{}/{}", src_dir, rec_file);
209:       print("recompiling {}\n", config.trim_by_root(file.str()));
210:       //rem output to trigger recompiling
211:       File::remove_file(get_out_file(file.str(), config.out_dir.str()).str())?;
212:       let ctx = Context::new(config.out_dir.clone(), config.std_path.clone());
213:       ctx.verbose_all = config.verbose_all;
214:       for(let j = 0;j < config.src_dirs.len();++j){
215:         ctx.add_path(config.src_dirs.get(j).str());
216:       }
217:       let cmp = Emitter::new(ctx, &config, &cache);
218:       let obj = cmp.compile(file.str());
219:       //compiled.add(obj);
220:       cmp.drop();
221:       file.drop();
222:     }
223:     list.drop();
224:     cache.drop();
225:     inc.drop();
226:     return config.link(&compiled);
227:   }
228: 
229:   func new_cache(config: CompilerConfig*): Cache{
230:     return Cache::new(config.incremental_enabled, config.use_cache, config.out_dir.str(), config.file.clone());
231:   }
232:   
233:   func compile_dir_thread(config: CompilerConfig): Result<String, CompilerError>{
234:     File::create_dir(config.out_dir.str())?;
235:     let cache = new_cache(&config);
236:     cache.read_cache();
237:     let src_dir = &config.file;
238:     let list: List<String> = File::read_dir(src_dir.str()).unwrap();
239:     let compiled = Mutex::new(List<String>::new());
240:     let worker = Worker::new(config.jobs);
241:     for(let i = 0;i < list.len();++i){
242:       let name = list.get(i).str();
243:       let file: String = format("{}/{}", src_dir, name);
244:       if(File::is_dir(file.str()) || !name.ends_with(".x")) {
245:         file.drop();
246:         continue;
247:       }
248:       let idx = Mutex::new(0);
249:       let args = CompileArgs{
250:         file: file.clone(),
251:         config: &config,
252:         cache: &cache,
253:         compiled: &compiled,
254:         idx: &idx,
255:         len: list.len() as i32,
256:       };
257:       worker.add_arg(Compiler::make_compile_job, args);
258:     }
259:     sleep(1);
260:     worker.join();
261:     list.drop();
262:     cache.drop();
263:     let comp = compiled.unwrap();
264:     return config.link(&comp);
265:   }
266: 
267:   func make_compile_job(arg: c_void*){
268:     let args = arg as CompileArgs*;
269:     let config = args.config;
270:     let ctx = Context::new(config.out_dir.clone(), config.std_path.clone());
271:     for dir in &config.src_dirs{
272:       ctx.add_path(dir.str());
273:     }
274:     let cmd = format("{} c -out {} -stdpath {} -nolink -cache", root_exe.get(), args.config.out_dir, args.config.std_path.get());
275:     for inc_dir in &args.config.src_dirs{
276:         cmd.append(" -i ");
277:         cmd.append(inc_dir);
278:     }
279:     if(config.opt_level.is_some()){
280:       cmd.append(" ");
281:       cmd.append(config.opt_level.get());
282:     }
283:     cmd.append(" ");
284:     cmd.append(&args.file);
285:     if(ctx.verbose){
286:       let idx = args.idx.lock();
287:       print("compiling {}\n", config.trim_by_root(args.file.str()));
288:       *idx = *idx + 1;
289:       args.idx.unlock();
290:     }
291:     let proc = Process::run(cmd.str());
292:     let code = proc.eat_close();
293:     if(code != 0){
294:       panic("failed to compile {}", args.file);
295:     }
296:     if(ctx.verbose){
297:       let idx = args.idx.lock();
298:       let compiled = args.compiled.lock();
299:       print("compiled [{}/{}] {}\n", compiled.len() + 1, args.len, config.trim_by_root(args.file.str()));
300:       args.compiled.unlock();
301:       args.idx.unlock();
302:     }
303:     let compiled = args.compiled.lock();
304:     compiled.add(format("{}", get_out_file(args.file.str(), config.out_dir.str())));
305:     args.compiled.unlock();
306:     sleep(1);
307:     ctx.drop();
308:     cmd.drop();
309:   }
