311:   func build_library(compiled: List<String>*, name: str, out_dir: str, is_shared: bool): Result<String, CompilerError>{
312:     File::create_dir(out_dir)?;
313:     let cmd = "".str();
314:     if(is_shared){
315:       cmd.append(get_linker());
316:       cmd.append("-shared -o ");
317:     }else{
318:       cmd.append(get_ar());
319:       cmd.append(" rcs ");
320:     }
321:     let out_file = format("{}/{}", out_dir, name);
322:     //print("linking {}\n", out_file);
323:     cmd.append(&out_file);
324:     cmd.append(" ");
325:     for file in compiled{
326:       cmd.append(file.str());
327:       cmd.append(" ");
328:     }
329: 
330:     let cmd_res = Process::run(cmd.str()).read_close();
331:     if(cmd_res.is_err()){
332:       let res = Result<String, CompilerError>::err(CompilerError::new(format("link failed '{}'\ncmd={}", cmd_res.get_err(), cmd)));
333:       cmd.drop();
334:       return res;
335:     }
336:     cmd_res.drop();
337:     print("build library {}\n", out_file);
338:     return Result<String, CompilerError>::ok(out_file);
339:   }
340:   
341:   func link(compiled: List<String>*, out_dir: str, name: str, args: str): Result<String, CompilerError>{
342:     let out_file = format("{}/{}", out_dir, name);
343:     //print("linking {}\n", out_file);
344:     if(File::exists(out_file.str())){
345:       File::remove_file(out_file.str())?;
346:     }
347:     File::create_dir(out_dir)?;
348:     let cmd = get_linker().str();
349:     cmd.append(" -o ");
350:     cmd.append(&out_file);
351:     cmd.append(" ");
352:     for obj_file in compiled{
353:       cmd.append(obj_file.str());
354:       cmd.append(" ");
355:     }
356:     cmd.append(args);
357:     //todo move this to main or bt.sh
358:     cmd.append(" -Wl,-rpath=$ORIGIN/../lib");
359:     File::write_string(cmd.str(), format("{}/link.sh", out_dir).str())?;
360:  
361:     let cmd_res = Process::run(cmd.str()).read_close();
362:     if(cmd_res.is_err()){
363:       return Result<String, CompilerError>::err(CompilerError::new(format("link failed '{}'\ncmd={}", cmd_res.get_err(), cmd)));
364:     }
365:     print("build binary {}\n", out_file);
366:     cmd.drop();
367:     return Result<String, CompilerError>::ok(out_file);
368:   }
