391: impl CompilerConfig{
392:   func set_std(self, std_path: String): CompilerConfig*{
393:     self.std_path.drop();
394:     self.std_path = Option::new(std_path);
395:     return self;
396:   }
397:   func set_std_path(self, std_path: str): CompilerConfig*{
398:     self.std_path.drop();
399:     self.std_path = Option::new(std_path.str());
400:     return self;
401:   }
402:   func set_out(self, out: str): CompilerConfig*{
403:     return self.set_out(out.str());
404:   }
405:   func set_out(self, out: String): CompilerConfig*{
406:     self.out_dir.drop();
407:     self.out_dir = out;
408:     return self;
409:   }
410:   func add_dir(self, dir: str): CompilerConfig*{
411:     self.src_dirs.add(dir.str());
412:     return self;
413:   }
414:   func add_dir(self, dir: String): CompilerConfig*{
415:     self.src_dirs.add(dir);
416:     return self;
417:   }
418:   func set_link(self, lt: LinkType): CompilerConfig*{
419:     self.lt = lt;
420:     return self;
421:   }
422:   func set_file(self, file: str): CompilerConfig*{
423:     return self.set_file(file.str());
424:   }
425:   func set_file(self, file: String): CompilerConfig*{
426:     self.file.drop();
427:     self.file = file;
428:     return self;
429:   }
430:   func set_jobs(self, j: i32): CompilerConfig*{
431:     if(j < 0){
432:       panic("invalid jobs {:?}", j);
433:     }
434:     self.jobs = j;
435:     return self;
436:   }
437:   func link(self, compiled: List<String>*): Result<String, CompilerError>{
438:     if(self.llvm_only) return Result<String, CompilerError>::ok("".owned());
439:     match &self.lt{
440:       LinkType::None => return Result<String, CompilerError>::ok("".owned()),
441:       LinkType::Binary(bin_name, args, run) => {
442:         let path = Compiler::link(compiled, self.out_dir.str(), bin_name.str(), args.str());
443:         if(path.is_ok() && *run){
444:           Compiler::run(path.get().clone());
445:         }
446:         return path;
447:       },
448:       LinkType::Static(lib_name) => {
449:         return Compiler::build_library(compiled, lib_name.str(), self.out_dir.str(), false);
450:       },
451:       LinkType::Dynamic(lib_name) => {
452:         return Compiler::build_library(compiled, lib_name.str(), self.out_dir.str(), true);
453:       },
454:     }
455:   }
456:   func trim_by_root(self, path: str): str{
457:     if(self.root_dir.is_none()){
458:       return path;
459:     }
460:     let root = self.root_dir.get();
461:     if(path.starts_with(root.str())){
462:       let res = path.substr(root.len());
463:       if(res.starts_with("/")){
464:         return res.substr(1, res.len());
465:       }
466:     }
467:     return path;
468:   }
469: }

